import { DomainError } from './errors.ts';

/**
 * A person who can sign in. `id` is generated by the control plane, opaque
 * and never reused; it is the only thing other records reference. `username`
 * and `displayName` may change at any time.
 */
export interface User {
  id: string;
  /** Unique login handle, lowercase, 3–32 of `[a-z0-9._-]`. */
  username: string;
  displayName: string;
  createdAt: string;
  updatedAt: string;
  /** Set once the user is disabled; a disabled user cannot sign in or be changed. */
  disabledAt?: string;
}

export interface NewUser {
  username: string;
  /** Defaults to the normalised username. */
  displayName?: string;
}

/**
 * Maps an identity provider's subject to a user. The local password provider
 * is provider `local` with the user's id as subject; an IdP (OIDC, SAML,
 * GitHub) links its own subject to a new or existing user id the same way.
 */
export interface ExternalIdentity {
  provider: string;
  subject: string;
  userId: string;
}

/** The provider name of the factory's own username and password login. */
export const localProvider = 'local';

/** Who is acting on a request. Services receive a `Principal`, never a username. */
export interface Principal {
  userId: string;
  via: 'session' | 'token';
}

/** Username and password, checked by the local provider. */
export interface PasswordCredentials {
  kind: 'password';
  username: string;
  password: string;
}

/**
 * What an `Authenticator` accepts, tagged by `kind`. An IdP adapter adds its
 * own variant here (for example `{ kind: 'oidc'; code: string }`).
 */
export type Credentials = PasswordCredentials;

export const usernameMinLength = 3;
export const usernameMaxLength = 32;
export const displayNameMaxLength = 100;

const usernamePattern = /^[a-z0-9._-]+$/;

/** Trims and lowercases; does not validate. Apply it before every lookup by username. */
export function normalizeUsername(username: string): string {
  return username.trim().toLowerCase();
}

/** The normalised username, or a `DomainError` `invalid_username`. */
export function parseUsername(username: string): string {
  const normalized = normalizeUsername(username);
  if (normalized.length < usernameMinLength || normalized.length > usernameMaxLength) {
    throw new DomainError(
      'invalid_username',
      `username must be ${usernameMinLength} to ${usernameMaxLength} characters long`,
    );
  }
  if (!usernamePattern.test(normalized)) {
    throw new DomainError('invalid_username', 'username may only contain a-z, 0-9, ".", "_" and "-"');
  }
  return normalized;
}

function parseDisplayName(displayName: string): string {
  const trimmed = displayName.trim();
  if (trimmed.length === 0 || trimmed.length > displayNameMaxLength) {
    throw new DomainError(
      'invalid_display_name',
      `display name must be 1 to ${displayNameMaxLength} characters long`,
    );
  }
  return trimmed;
}

function assertActive(user: User): void {
  if (user.disabledAt !== undefined) {
    throw new DomainError('user_disabled', `user ${user.id} is disabled`);
  }
}

/**
 * Throws `duplicate_username` when `holder`, the user the repository returned
 * for the username, is another user than `userId`. The repository's unique
 * index stays the final guard against races.
 */
export function assertUsernameAvailable(username: string, holder: User | undefined, userId?: string): void {
  if (holder !== undefined && holder.id !== userId) {
    throw new DomainError('duplicate_username', `username ${username} is taken`);
  }
}

/** Throws `unknown_user` when the user does not exist, and `user_disabled` when it is disabled. */
export function assertActiveUser(user: User | undefined, userId: string): User {
  if (user === undefined) {
    throw new DomainError('unknown_user', `user ${userId} does not exist`);
  }
  assertActive(user);
  return user;
}

// Pure, like the task and project operations: the caller stamps `updatedAt`
// when saving and checks username uniqueness against its repository.

export function createUser(input: NewUser, meta: { id: string; now: string }): User {
  const username = parseUsername(input.username);
  return {
    id: meta.id,
    username,
    displayName: parseDisplayName(input.displayName ?? username),
    createdAt: meta.now,
    updatedAt: meta.now,
  };
}

/** Changes the display name. */
export function renameUser(user: User, displayName: string): User {
  assertActive(user);
  return { ...user, displayName: parseDisplayName(displayName) };
}

/** Changes the login handle; the id, and so every reference to the user, stays. */
export function changeUsername(user: User, username: string): User {
  assertActive(user);
  return { ...user, username: parseUsername(username) };
}

/** Disables the user for good; disabling again keeps the first `disabledAt`. */
export function disableUser(user: User, now: string): User {
  if (user.disabledAt !== undefined) return user;
  return { ...user, disabledAt: now };
}

export function isActiveUser(user: User): boolean {
  return user.disabledAt === undefined;
}
